+                    + Arrays.toString(expected)
+                    + "\nActual:   "
+                    + Arrays.toString(actual)
+            );
+        }
+    }
+
+    private static void assertThrows(
+        Class<? extends Throwable> expectedType,
+        Runnable action,
+        String message
+    ) {
+        try {
+            action.run();
+        } catch (Throwable error) {
+            if (expectedType.isInstance(error)) {
+                return;
+            }
+
+            throw new AssertionError(
